27	/// Parses the external binaries to bundle, adding the target triple suffix to each of them.
28	pub fn external_binaries(external_binaries: &[String], target_triple: &str) -> Vec<String> {
29	  let mut paths = Vec::new();
30	  for curr_path in external_binaries {
31	    paths.push(format!(
32	      "{}-{}{}",
33	      curr_path,
34	      target_triple,
35	      if target_triple.contains("windows") {
36	        ".exe"
37	      } else {
38	        ""
39	      }
40	    ));
41	  }
42	  paths
43	}
