94	/// Copies resources to a path.
95	fn copy_resources(resources: ResourcePaths<'_>, path: &Path) -> Result<()> {
96	  let path = path.canonicalize()?;
97	  for resource in resources.iter() {
98	    let resource = resource?;
99	
100	    println!("cargo:rerun-if-changed={}", resource.path().display());
101	
102	    // avoid copying the resource if target is the same as source
103	    let src = resource.path().canonicalize()?;
104	    let target = path.join(resource.target());
105	    if src != target {
106	      copy_file(src, target)?;
107	    }
108	  }
109	  Ok(())
110	}
