135	fn copy_dir(from: &Path, to: &Path) -> Result<()> {
136	  for entry in walkdir::WalkDir::new(from) {
137	    let entry = entry?;
138	    debug_assert!(entry.path().starts_with(from));
139	    let rel_path = entry.path().strip_prefix(from)?;
140	    let dest_path = to.join(rel_path);
141	    if entry.file_type().is_symlink() {
142	      let target = std::fs::read_link(entry.path())?;
143	      if entry.path().is_dir() {
144	        symlink_dir(&target, &dest_path)?;
145	      } else {
146	        symlink_file(&target, &dest_path)?;
147	      }
148	    } else if entry.file_type().is_dir() {
149	      std::fs::create_dir(dest_path)?;
150	    } else {
151	      std::fs::copy(entry.path(), dest_path)?;
152	    }
153	  }
154	  Ok(())
155	}
