169	// Copies the macOS application bundle frameworks to the target folder
170	fn copy_frameworks(dest_dir: &Path, frameworks: &[String]) -> Result<()> {
171	  std::fs::create_dir_all(dest_dir)
172	    .with_context(|| format!("Failed to create frameworks output directory at {dest_dir:?}"))?;
173	  for framework in frameworks.iter() {
174	    if framework.ends_with(".framework") {
175	      let src_path = PathBuf::from(framework);
176	      let src_name = src_path
177	        .file_name()
178	        .expect("Couldn't get framework filename");
179	      let dest_path = dest_dir.join(src_name);
180	      copy_dir(&src_path, &dest_path)?;
181	      continue;
182	    } else if framework.ends_with(".dylib") {
183	      let src_path = PathBuf::from(framework);
184	      if !src_path.exists() {
185	        return Err(anyhow::anyhow!("Library not found: {}", framework));
186	      }
187	      let src_name = src_path.file_name().expect("Couldn't get library filename");
188	      let dest_path = dest_dir.join(src_name);
189	      copy_file(&src_path, &dest_path)?;
190	      continue;
191	    } else if framework.contains('/') {
192	      return Err(anyhow::anyhow!(
193	        "Framework path should have .framework extension: {}",
194	        framework
195	      ));
196	    }
197	    if let Some(home_dir) = dirs::home_dir() {
198	      if copy_framework_from(&home_dir.join("Library/Frameworks/"), framework, dest_dir)? {
199	        continue;
200	      }
201	    }
202	    if copy_framework_from(&PathBuf::from("/Library/Frameworks/"), framework, dest_dir)?
203	      || copy_framework_from(
204	        &PathBuf::from("/Network/Library/Frameworks/"),
205	        framework,
206	        dest_dir,
207	      )?
208	    {
209	      continue;
210	    }
211	  }
212	  Ok(())
213	}
